def get_acft_icao():
    sb = getSimbrief()

    code = str(getattr(sb, "icao_airline", None)).strip().upper()
    acft_code = str(getattr(aircraft, "icaoAirline", None)).strip().upper()

    if not code and not acft_code:
        return None

    if code != acft_code:
        return acft_code
    else:
        return code

def pick_route(gate_name, base_pos, base_paths, ns_pos, ns_paths, is_schengen):
    if not is_schengen and gate_name in ns_pos:
        return ns_pos[gate_name], ns_paths[gate_name]
    if gate_name in base_pos:
        return base_pos[gate_name], base_paths[gate_name]
    return None, None

def apply_handler():
    gate = getGate()

    if not gate:
        return

    icao = get_acft_icao()
    gate.handlingTexture = "Havas" if icao in HAVAS else "RIX"
    gate.cateringTexture = "LSG"
    gate.fuelTruckTexture = "BGS"
    print(f"{LOG_PREFIX}acft_icao: {icao}, handler: {gate.handlingTexture}")

    name = gate.uiGateName
    if (name not in JETWAY_GATE_POS
            and name not in WALK_IN_GATE_POS
            and name not in WALK_IN_GATE_POS_NON_SCHENGEN):
        return

    sb = getSimbrief()
    destination_icao = str(getattr(sb, "destinationICAO", None)).strip().upper()[:2]
    is_schengen = destination_icao in SCHENGEN_ICAOS

    has_jetway = name in JETWAY_GATE_POS
    boards_on_apron = not is_schengen and name in WALK_IN_GATE_POS_NON_SCHENGEN
    use_walk_in = not has_jetway or icao in LOW_COST or boards_on_apron
    print(f"{LOG_PREFIX}has_jetway: {has_jetway}, boards_on_apron: {boards_on_apron}, use_walk_in: {use_walk_in}, is_schengen: {is_schengen}, destination_icao: {destination_icao}")

    if use_walk_in:
        gate.hasJetway = 0
        gate.noPassengerStairs = False
        pos, paths = pick_route(name, WALK_IN_GATE_POS, WALK_IN_PATHS,
                                WALK_IN_GATE_POS_NON_SCHENGEN, WALK_IN_GATE_PATHS_NON_SCHENGEN,
                                is_schengen)
        if pos:
            gate.passengerEnterGatePos = pos
            gate.passengerWaypoints = paths
        if name in WALK_IN_GATE_POS_DEBOARDING:
            gate.passengerEnterGatePos_deboarding = WALK_IN_GATE_POS_DEBOARDING[name]
            gate.passengerWaypoints_deboarding = WALK_IN_PATHS_DEBOARDING[name]
    else:
        gate.noPassengerStairs = True
        gate.hasJetway = 1
        gate.jetwayEnterGatePos = JETWAY_GATE_POS[name]
        gate.jetwayWaypoints = JETWAY_GATE_PATHS[name]
        gate.jetwayEnterGatePos_deboarding = JETWAY_GATE_POS_DEBOARDING[name]
        gate.jetwayWaypoints_deboarding = JETWAY_GATE_PATHS_DEBOARDING[name]

def onAirportBeforeVehicleSelect(self):
    apply_handler()

def onAircraftEngaged(self):
    apply_handler()

def onVehicleCandidatesScored(self, vehicleType, candidates):
    if vehicleType not in ["Staircase", "BaggageTractor", "BaggageWagon", "Pushback"]:
        return
    
    if vehicleType == "Staircase":
        for c in candidates:
            if 'CDS_2445' in c.title and aircraft.idMajor in CDS_ACFT:
                c.boostScore(10)
            if 'ABS-580' in c.title and aircraft.idMajor in ABS_ACFT:
                c.boostScore(10)
    if vehicleType == "BaggageTractor":
        for c in candidates:
            if 'JET_16' in c.title:
                c.boostScore(10)
    if vehicleType == "Pushback":
        for c in candidates:
            if 'TMX_150' in c.title or 'TPX_100_E' in c.title:
                c.boostScore(10)
    if vehicleType == "BaggageWagon":
        for c in candidates:
            if 'Closed' in c.title:
                c.boostScore(10)
